// === Tab: sketch ===
// By Roni Kaufman
// https://ronikaufman.github.io

let theta, a, b;

function setup() {
  createCanvas(600, 600, WEBGL);
	pixelDensity(1);
  noStroke();
	// noLoop() removed for animation
}

function draw() {
  let palette1 = ["#abcd5e", "#14976b", "#2b67af", "#62b6de", "#f589a3", "#ef562f", "#fc8405", "#f9d531"];
  let palette2 = shuffle(["#050505", "#fffbe6"]);
  background(random(palette2));

  let n = 32; // number of arcs
  theta = PI/n;
  a = tan(theta)/sqrt(1+sq(tan(theta)));
  b = (1+a)/(1-a);
  let l0 = 50;

	let j = 0;
	for (let i = 0; i < n; i++) {
		fill(palette2[(j++)%2]);
		circle(0, l0, 2*l0*a);
		rotate(2*theta);
	}

  let l = l0;
  let _wG_1 = 0; while ((l < width) && ++_wG_1 < 20000) {
    let r = l*a;
    for (let i = 0; i < n; i++) {
			if (random() < 1/2) {
				fill(palette1[(i+j)%palette1.length]);
				portion(l);
				fill(palette2[(i+j)%2]);
				arcNW(l, r);
				arcSE(l, r);
				fill(palette2[1-(i+j)%2]);
				arcSW(l, r);
				arcNE(l, r);
			} else {
				if (random() < 1/2) {
					fill(palette2[1-(i+j)%2]);
					portion(l);
					fill(palette2[(i+j)%2]);
					arcNW(l, r);
					arcSE(l, r);
				} else {
					fill(palette2[(i+j)%2]);
					portion(l);
					fill(palette2[1-(i+j)%2]);
					arcSW(l, r);
					arcNE(l, r);
				}
			}

			// fix the little lines between the tiles
			stroke(palette2[(i+j)%2]);
			strokeWeight(1.5);
			noFill();
			arc(0, 0, 2*l, 2*l, -theta+0.004, theta-0.004);
			noStroke();

      rotate(2*theta);
    }

    l *= b;
		j++;
  }
}

function arcNW(l, r) {
	let notHalfPi = atan2(l*sin(theta), l*cos(theta)-l);
	//arc(l, 0, 2*r, 2*r, 0, notHalfPi);
	beginShape();
	vertex(l, 0);
	for (let th = 0; th < notHalfPi; th += (Math.max(0.001, Math.abs(TAU/100)) || 1)) {
		vertex(l+r*cos(th), r*sin(th));
	}
	for (let th = theta; th > 0; th -= TAU/100) {
		vertex(l*cos(th), l*sin(th));
	}
	endShape();
}

function arcSW(l, r) {
	rotate(2*theta);
	var notHalfPi = atan2(l*sin(theta), l*cos(theta)-l);
	//arc(l, 0, 2*r, 2*r, TAU-notHalfPi, TAU);
	beginShape();
	vertex(l, 0);
	for (let th = TAU; th > TAU-notHalfPi; th -= TAU/100) {
		vertex(l+r*cos(th), r*sin(th));
	}
	for (let th = -theta; th < 0; th += (Math.max(0.001, Math.abs(TAU/100)) || 1)) {
		vertex(l*cos(th), l*sin(th));
	}
	endShape();
	rotate(-2*theta);
}

function arcSE(l, r) {
	rotate(2*theta);
	let l1 = l*b, r1 = l1*a;
	let notHalfPi1 = atan2(l1*sin(theta), l1*cos(theta)-l1);
	//arc(l1, 0, 2*r1, 2*r1, PI, TAU-notHalfPi1);
	beginShape();
	vertex(l1, 0);
	for (let th = PI; th < TAU-notHalfPi1; th += (Math.max(0.001, Math.abs(TAU/100)) || 1)) {
		vertex(l1+r1*cos(th), r1*sin(th));
	}
	for (let th = -theta; th < 0; th += (Math.max(0.001, Math.abs(TAU/100)) || 1)) {
		vertex(l1*cos(th), l1*sin(th));
	}
	endShape();
	rotate(-2*theta);
}

function arcNE(l, r) {
	var l1 = l*b, r1 = l1*a;
	var notHalfPi1 = atan2(l1*sin(theta), l1*cos(theta)-l1);
	//arc(l1, 0, 2*r1, 2*r1, notHalfPi1, PI);
	beginShape();
	vertex(l1, 0);
	for (let th = PI; th > notHalfPi1; th -= TAU/100) {
		vertex(l1+r1*cos(th), r1*sin(th));
	}
	for (let th = theta; th > 0; th -= TAU/100) {
		vertex(l1*cos(th), l1*sin(th));
	}
	endShape();
}

function portion(l) {
	var l1 = l*b;
	beginShape();
	vertex(l1*cos(0), l1*sin(0));
	for (let th = 0; th <= 2*theta; th += (Math.max(0.001, Math.abs(TAU/100)) || 1)) {
		vertex(l1*cos(th), l1*sin(th));
	}
	vertex(l1*cos(2*theta), l1*sin(2*theta));
	vertex(l*cos(2*theta), l*sin(2*theta));
	for (let th = 2*theta; th >= 0; th -= TAU/100) {
		vertex(l*cos(th), l*sin(th));
	}
	vertex(l*cos(0), l*sin(0));
	endShape(CLOSE);
}
